// GENERATED by scripts/sync-readiness.mjs from apps/api/src/readiness/security.ts. Do not edit.
/* eslint-disable */

import type { AndroidFacts, IosFacts, SecretHit, SecretKind, SecurityFacts } from './readiness.gen';
import { ADVISORIES_CHECKED, matchAdvisories } from './advisories';

// Security scan: findings from the facts the worker read at upload (meta.facts.security, worker/security.ts),
// mapped to the OWASP MASVS categories. Pure and cheap like the store readiness rules (rules.ts), so new
// checks apply to every scanned build on the next read. Builds uploaded before the scan existed stay "not
// scanned". Copy: plain words, no dashes, no emojis, never "secure" or "certified": these are hints and
// findings, not a security verdict.

export type SecLevel = 'block' | 'warn' | 'info';
export type Masvs = 'MASVS-STORAGE' | 'MASVS-CRYPTO' | 'MASVS-AUTH' | 'MASVS-NETWORK' | 'MASVS-PLATFORM' | 'MASVS-CODE' | 'MASVS-RESILIENCE';

export type SecurityFinding = { id: string; level: SecLevel; area: 'security'; masvs: Masvs; title: string; detail: string; fix: string; refs?: string[] };

export type Counts = { block: number; warn: number; info: number };

export type SecurityReport = {
  /** unknown = not scanned (uploaded before the scan existed, or the scan failed). */
  status: 'scanned' | 'unknown';
  findings: SecurityFinding[];
  passed: string[];
  checked: number;
  counts: Counts;
  /** "1 to fix, 3 warnings, 2 notes": a count, not a score. */
  summary: string;
  groups: { masvs: Masvs; title: string; counts: Counts }[];
  /** A size or time cap stopped the scan before the end of the build. */
  capped: boolean;
  advisoriesChecked: string;
};

export const MASVS_TITLES: Record<Masvs, string> = {
  'MASVS-STORAGE': 'Storage: sensitive data in the app and its backups',
  'MASVS-CRYPTO': 'Cryptography: keys and how they are kept',
  'MASVS-AUTH': 'Authentication',
  'MASVS-NETWORK': 'Network: TLS and what the app trusts',
  'MASVS-PLATFORM': 'Platform: components, WebViews and what other apps can reach',
  'MASVS-CODE': 'Code: platform versions and third party libraries',
  'MASVS-RESILIENCE': 'Resilience: debugging, symbols, obfuscation and tamper checks',
};
const MASVS_ORDER = Object.keys(MASVS_TITLES) as Masvs[];

export type SecurityInput = { platform: 'IOS' | 'ANDROID' | 'MACOS' | 'WINDOWS'; meta: unknown };

const SECRET_TEXT: Record<Exclude<SecretKind, 'google-api-key'>, { title: string; masvs: Masvs; level: SecLevel; what: string; fix: string }> = {
  'aws-access-key': {
    title: 'AWS access key in the build',
    masvs: 'MASVS-STORAGE',
    level: 'block',
    what: 'An AWS access key id ships inside the app. Anyone can unzip the build and read it; with its secret key it works against your AWS account.',
    fix: 'Deactivate the key in AWS IAM now, then move the call behind your own server or use short lived credentials (for example Cognito identity pools). Do not ship long lived AWS keys in an app.',
  },
  'stripe-live-secret': {
    title: 'Stripe live secret key in the build',
    masvs: 'MASVS-STORAGE',
    level: 'block',
    what: 'A Stripe live secret or restricted key ships inside the app. It can create charges, refunds and read customer data from anyone who unzips the build.',
    fix: 'Roll the key in the Stripe Dashboard now. Apps should only hold the publishable key (pk_live_); do payments through your own server.',
  },
  'private-key': {
    title: 'Private key in the build',
    masvs: 'MASVS-CRYPTO',
    level: 'block',
    what: 'A PEM private key ships inside the app. Whatever it signs or decrypts can be done by anyone who unzips the build.',
    fix: 'Treat the key as exposed: replace it and revoke the old one. Keep private keys on a server, or create them on the device in the Keychain or Android Keystore.',
  },
  'google-service-account': {
    title: 'Google service account key in the build',
    masvs: 'MASVS-STORAGE',
    level: 'block',
    what: 'A Google Cloud service account JSON key (private_key and client_email) ships inside the app. It acts as that service account for anyone who unzips the build.',
    fix: 'Delete the key in Google Cloud IAM now and remove the file from the app. Call Google APIs from your server, or use Firebase with security rules or App Check.',
  },
  'slack-token': {
    title: 'Slack token in the build',
    masvs: 'MASVS-STORAGE',
    level: 'block',
    what: 'A Slack API token ships inside the app and can act in your Slack workspace for anyone who unzips the build.',
    fix: 'Revoke the token in the Slack app settings and send messages through your own server instead.',
  },
  'slack-webhook': {
    title: 'Slack webhook address in the build',
    masvs: 'MASVS-STORAGE',
    level: 'warn',
    what: 'A Slack incoming webhook address ships inside the app. Anyone who unzips the build can post messages to that channel.',
    fix: 'Make a new webhook in Slack, delete the old one, and post through your own server.',
  },
  'github-token': {
    title: 'GitHub token in the build',
    masvs: 'MASVS-STORAGE',
    level: 'block',
    what: 'A GitHub token ships inside the app and gives its access to your repositories or organization to anyone who unzips the build.',
    fix: 'Revoke the token in GitHub settings now and call GitHub from your own server.',
  },
  'firebase-server-key': {
    title: 'Firebase Cloud Messaging server key in the build',
    masvs: 'MASVS-STORAGE',
    level: 'block',
    what: 'A legacy Firebase Cloud Messaging server key ships inside the app. With it anyone can send push messages to your users.',
    fix: 'Remove the key from the app and send pushes from your server with the FCM HTTP v1 API (the legacy server keys are retired).',
  },
};

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`;
const listOf = (xs: string[], max = 6) => (xs.length > max ? `${xs.slice(0, max).join(', ')} and ${xs.length - max} more` : xs.join(', '));

export function summaryText(c: Counts): string {
  const parts = [c.block && `${c.block} to fix`, c.warn && plural(c.warn, 'warning'), c.info && plural(c.info, 'note')].filter(Boolean) as string[];
  return parts.length ? parts.join(', ') : 'No findings';
}

export function countLevels(findings: { level: SecLevel }[]): Counts {
  const c: Counts = { block: 0, warn: 0, info: 0 };
  for (const f of findings) c[f.level]++;
  return c;
}

class Runner {
  findings: SecurityFinding[] = [];
  passed: string[] = [];
  checked = 0;
  check(name: string, fail: SecurityFinding | null) {
    this.checked++;
    if (fail) this.findings.push(fail);
    else this.passed.push(name);
  }
  /** One check that can fail with several findings. */
  many(name: string, fails: SecurityFinding[]) {
    this.checked++;
    if (fails.length) this.findings.push(...fails);
    else this.passed.push(name);
  }
  note(f: SecurityFinding) {
    this.findings.push(f);
  }
}

const f = (id: string, level: SecLevel, masvs: Masvs, title: string, detail: string, fix: string, refs?: string[]): SecurityFinding => ({
  id,
  level,
  area: 'security',
  masvs,
  title,
  detail,
  fix,
  ...(refs?.length ? { refs } : {}),
});

/** Security facts of a build, or null when it was not scanned. */
export function securityFacts(meta: unknown): SecurityFacts | null {
  const s = (meta as { facts?: { security?: SecurityFacts | null } } | null)?.facts?.security;
  return s && typeof s === 'object' && Array.isArray(s.secrets) ? s : null;
}

export function securityScan(b: SecurityInput): SecurityReport {
  const s = securityFacts(b.meta);
  if (!s) return { status: 'unknown', findings: [], passed: [], checked: 0, counts: { block: 0, warn: 0, info: 0 }, summary: 'Not scanned', groups: [], capped: false, advisoriesChecked: ADVISORIES_CHECKED };
  const r = new Runner();
  const facts = ((b.meta as { facts?: unknown }).facts ?? {}) as AndroidFacts & IosFacts;

  secrets(r, s.secrets);
  if (b.platform === 'ANDROID') android(r, b, facts, s);
  else ios(r, b, facts, s);

  r.many(
    'No library versions with a known advisory',
    matchAdvisories(s.libs ?? []).map(({ advisory: a, version }) =>
      f(`sec.lib.${a.id}`, a.level, 'MASVS-CODE', `${a.label} ${version} has a known vulnerability (${a.cve})`, `${a.detail} Affected: ${a.label} ${a.range}. Published ${a.year}.`, a.fix, [a.url]),
    ),
  );

  r.note(rasp(b.platform, s.rasp ?? []));

  const order: Record<SecLevel, number> = { block: 0, warn: 1, info: 2 };
  r.findings.sort((x, y) => order[x.level] - order[y.level] || MASVS_ORDER.indexOf(x.masvs) - MASVS_ORDER.indexOf(y.masvs));
  const counts = countLevels(r.findings);
  const groups = MASVS_ORDER.map((m) => ({ masvs: m, title: MASVS_TITLES[m], counts: countLevels(r.findings.filter((x) => x.masvs === m)) })).filter((g) => g.counts.block + g.counts.warn + g.counts.info > 0);
  return { status: 'scanned', findings: r.findings, passed: r.passed, checked: r.checked, counts, summary: summaryText(counts), groups, capped: !!s.scan?.capped, advisoriesChecked: ADVISORIES_CHECKED };
}

// ---------------------------------------------------------------- secrets

function secrets(r: Runner, hits: SecretHit[]) {
  const byKind = new Map<SecretKind, SecretHit[]>();
  for (const h of hits) byKind.set(h.kind, [...(byKind.get(h.kind) ?? []), h]);
  const where = (xs: SecretHit[]) => listOf(xs.map((h) => `${h.masked} in ${h.file}`), 5);
  const hardcoded = [...byKind.keys()].filter((k) => k !== 'google-api-key');
  r.many(
    'No hardcoded secret keys found',
    hardcoded.map((kind) => {
      const t = SECRET_TEXT[kind as Exclude<SecretKind, 'google-api-key'>];
      const xs = byKind.get(kind)!;
      return f(`sec.secret.${kind}`, t.level, t.masvs, xs.length > 1 ? `${t.title} (${xs.length})` : t.title, `${t.what} Found: ${where(xs)}.`, t.fix);
    }),
  );
  const google = byKind.get('google-api-key') ?? [];
  if (google.length) {
    r.note(f('sec.secret.google-api-key', 'info', 'MASVS-STORAGE', `${plural(google.length, 'Google API key')} in the build`,
      `Google API keys (AIza...) are meant to ship in apps, for example in google-services.json, so this is not a leak by itself. A key without restrictions can be used by anyone for any API it allows, on your bill. Found: ${where(google)}.`,
      'In Google Cloud Console, restrict each key to your app (Android package and SHA-1, or iOS bundle id) and to the APIs it needs.'));
  }
}

// ---------------------------------------------------------------- Android

function android(r: Runner, b: SecurityInput, x: AndroidFacts, s: SecurityFacts) {
  const a = s.android;
  const meta = (b.meta ?? {}) as { minSdk?: string | null; debuggable?: boolean };
  if (a) {
    r.check(
      'App data left out of backups, or backup rules set',
      a.allowBackup !== false && !a.backupRules
        ? f('sec.android.backup', 'warn', 'MASVS-STORAGE', a.allowBackup === null ? 'App data is backed up (Android default)' : 'App data is backed up (allowBackup on)',
            `${a.allowBackup === null ? 'The manifest does not set android:allowBackup, so Android backs up' : 'android:allowBackup is true, so Android backs up'} the app's files, databases and shared preferences to the user's cloud backup and copies them in device to device transfers, with no rules on what is left out. Tokens or personal data stored there leave the device.`,
            'Set android:allowBackup="false", or keep it on and add android:dataExtractionRules (Android 12 and later) and android:fullBackupContent rules that leave out tokens, keys and caches.')
        : null,
    );

    r.check(
      'No exported components without a permission',
      a.exportedTotal
        ? f('sec.android.exported', 'warn', 'MASVS-PLATFORM', `${plural(a.exportedTotal, 'exported component')} without a permission`,
            `${listOf(a.exported.map((e) => `${e.name} (${e.kind})`), 8)}. Any app on the device can start or send data to these. That is right for deep link and share targets, but each one has to check what it receives.`,
            'Set android:exported="false" on everything other apps do not need. For the rest, add android:permission (a signature permission for your own apps) or check the caller and validate every extra and URI.')
        : null,
    );

    if (x.stack === 'native' && a.minify) {
      const ratio = a.minify.short / a.minify.classes;
      r.check(
        'Code shrunk and obfuscated (a hint)',
        ratio < 0.15
          ? f('sec.android.minify', 'info', 'MASVS-RESILIENCE', 'Code does not look shrunk or obfuscated (a hint)',
              `${a.minify.classes - a.minify.short} of ${a.minify.classes} classes in classes.dex keep readable names, which usually means R8 (or ProGuard) did not run on this build. Readable code is easier to read back and patch, and the app is larger. This is a hint from class names, not proof.`,
              'Set isMinifyEnabled = true (and isShrinkResources = true) for the release build type in build.gradle, keep rules for reflection, and test the release build.')
          : null,
      );
    }

    if (a.webviewDebug) {
      r.note(f('sec.android.webview-debug', 'info', 'MASVS-PLATFORM', 'WebView debugging is referenced in the code',
        'The code calls WebView.setWebContentsDebuggingEnabled. When it is turned on in a release build, anyone with a USB cable can inspect and change the WebView pages. Many libraries call it only for debug builds, so this is a hint.',
        'Only call setWebContentsDebuggingEnabled(true) when BuildConfig.DEBUG is true.'));
    }

    if (a.userCerts !== null) {
      r.check(
        'Network config does not trust user added certificates',
        a.userCerts
          ? f('sec.android.user-certs', 'warn', 'MASVS-NETWORK', 'Network config trusts user added certificates',
              'The network security config trusts certificates the user (or a device management profile) installed, outside debug-overrides. Anyone who gets a CA onto the phone can read and change the app\'s HTTPS traffic.',
              'Remove <certificates src="user"/> from base-config and domain-config, and keep it inside <debug-overrides> only, which applies to debuggable builds.')
          : null,
      );
    }
  }

  r.check(
    'Not a debuggable build',
    meta.debuggable
      ? f('sec.android.debuggable', 'warn', 'MASVS-RESILIENCE', 'Debuggable build',
          'android:debuggable is on, so anyone with the phone can attach a debugger, read the app\'s private files with run-as and change its behaviour. Fine for testers, never for release.',
          'Build the release variant for anything that leaves your team.')
      : null,
  );

  r.check(
    'Plain HTTP not allowed for every server',
    x.cleartextTraffic && !x.networkSecurityConfig
      ? f('sec.android.cleartext', 'warn', 'MASVS-NETWORK', 'Plain HTTP allowed for every server',
          'usesCleartextTraffic is on, so the app may send traffic unencrypted to any host, where it can be read and changed on the network.',
          'Turn it off and allow HTTP only for the hosts that need it in a network security config.')
      : null,
  );

  const minSdk = Number(meta.minSdk);
  if (Number.isFinite(minSdk) && minSdk > 0) {
    r.check(
      'Minimum Android 7.0 (API 24) or later',
      minSdk < 24
        ? f('sec.android.minsdk', 'info', 'MASVS-CODE', `Runs on Android versions without current security updates (minimum API ${minSdk})`,
            `The app installs on Android older than 7.0 (API 24). Those versions no longer get security updates, and some protections (for example trusting only system certificates by default, from API 24) are missing there.`,
            'Raise minSdk to 24 or higher when your users allow it.')
        : null,
    );
  }
}

// ---------------------------------------------------------------- iOS

function ios(r: Runner, b: SecurityInput, x: IosFacts, s: SecurityFacts) {
  const i = s.ios;
  const meta = (b.meta ?? {}) as { distribution?: string };

  r.check(
    'App Transport Security on for every domain',
    x.atsArbitraryLoads
      ? f('sec.ios.ats', 'warn', 'MASVS-NETWORK', 'Insecure network loads allowed for every domain',
          'NSAllowsArbitraryLoads is on, so the app may load plain HTTP and weak TLS from any server, where traffic can be read and changed.',
          'Turn it off and add NSExceptionDomains only for the servers that still need it.')
      : null,
  );
  if (!i) return;

  if (i.atsExceptions.length) {
    const desc = i.atsExceptions.map((e) => {
      const what = [e.insecureHttp && 'plain HTTP', e.minTls && `TLS from ${e.minTls.replace(/^TLSv/, '')}`, e.noForwardSecrecy && 'no forward secrecy'].filter(Boolean).join(', ');
      return `${e.domain}${e.subdomains ? ' and subdomains' : ''}${what ? ` (${what})` : ''}`;
    });
    r.note(f('sec.ios.ats-domains', 'info', 'MASVS-NETWORK', `${plural(i.atsExceptions.length, 'App Transport Security exception')}`,
      `${listOf(desc, 8)}. Each exception loosens HTTPS rules for that server. Test and internal hosts are a common leftover in release builds.`,
      'Remove exceptions for test and internal servers, and move the rest to HTTPS with TLS 1.2 or later.'));
  }

  if (i.atsWebContent) {
    r.note(f('sec.ios.ats-web', 'info', 'MASVS-NETWORK', 'Insecure loads allowed in web views',
      'NSAllowsArbitraryLoadsInWebContent is on, so pages in WKWebView may load plain HTTP from any server. That suits browsers; other apps rarely need it.',
      'Remove NSAllowsArbitraryLoadsInWebContent unless the app shows arbitrary web pages.'));
  }

  if (i.localSymbols !== null) {
    r.check(
      'Symbols stripped from the app binary',
      i.localSymbols > 10
        ? f('sec.ios.symbols', 'info', 'MASVS-RESILIENCE', 'Symbols not stripped from the app binary',
            `The main binary keeps ${i.localSymbols.toLocaleString('en-US')} local symbols (function and type names). They make the app easier to read back, and Xcode removes them from archived release builds by default.`,
            'Build with Archive (Release), keep Strip Linked Product and Deployment Postprocessing on, and keep the dSYM for crash reports.')
        : null,
    );
  }

  if (i.getTaskAllow !== null) {
    r.check(
      'Debugging entitlement off outside development builds',
      i.getTaskAllow && meta.distribution !== 'development'
        ? f('sec.ios.get-task-allow', 'warn', 'MASVS-RESILIENCE', 'Debugging allowed (get-task-allow) in a non development build',
            `The binary is signed with get-task-allow true, which lets a debugger attach, but the build is signed for ${meta.distribution ?? 'distribution'}. Release builds should not carry it.`,
            'Export with Ad Hoc, Enterprise or App Store signing from an archive, so Xcode signs without get-task-allow.')
        : null,
    );
  }
}

// ---------------------------------------------------------------- RASP

function rasp(platform: 'IOS' | 'ANDROID' | 'MACOS' | 'WINDOWS', found: string[]): SecurityFinding {
  if (found.length) {
    return f('sec.rasp.found', 'info', 'MASVS-RESILIENCE', `Integrity and tamper checks found: ${found.join(', ')}`,
      `The build includes ${listOf(found)}. Some of these come with other SDKs (for example Firebase Authentication uses Play Integrity), so check that your app acts on the result. These checks raise the effort for an attacker; they do not make an app safe on their own.`,
      'Keep the checks on the server side where you can (verify Play Integrity or App Attest tokens on your server), and test the release build on a rooted or jailbroken device.');
  }
  return f('sec.rasp.none', 'info', 'MASVS-RESILIENCE', `No ${platform === 'IOS' ? 'jailbreak' : 'root'} or tamper detection found`,
    `No known ${platform === 'IOS' ? 'jailbreak detection or App Attest' : 'root detection, Play Integrity'} or tamper check library was found in the build. Most apps do not need one; apps that handle payments, health or other high value data often add one.`,
    platform === 'IOS'
      ? 'If the app needs it, verify App Attest assertions on your server, or add a maintained jailbreak detection library.'
      : 'If the app needs it, verify Play Integrity verdicts on your server, or add a maintained root detection library.');
}

/** Findings with secrets reduced to kind and file, for the AI fix plan (masked values never go to the AI). */
export function aiSafe(findings: SecurityFinding[]): { level: SecLevel; masvs: Masvs; title: string; detail: string; fix: string }[] {
  return findings.map((x) => ({
    level: x.level,
    masvs: x.masvs,
    title: x.title,
    detail: x.id.startsWith('sec.secret.') ? x.detail.replace(/Found: .*$/, 'Found in the build files (values not shown).') : x.detail,
    fix: x.fix,
  }));
}
